typedef struct{const uint8_t*p,*e;}R;static void die(const char*s){fprintf(stderr,"%s\n",s);exit(1);}static const uint8_t*take(R*r,size_t n){const uint8_t*p=r->p;if(p+n>r->e)die("truncated");r->p+=n;return p;}static uint8_t u8(R*r){return*take(r,1);}static uint16_t u16(R*r){uint16_t v;memcpy(&v,take(r,2),2);return v;}static uint32_t u32(R*r){uint32_t v;memcpy(&v,take(r,4),4);return v;}static uint64_t u64(R*r){uint64_t v;memcpy(&v,take(r,8),8);return v;}static uint32_t at32(const uint8_t*p,size_t o){uint32_t v;memcpy(&v,p+o,4);return v;}static uint16_t at16(const uint8_t*p,size_t o){uint16_t v;memcpy(&v,p+o,2);return v;}
static uint8_t*inflate(const char*p,size_t*n){FILE*f=fopen(p,"rb");if(!f)die("open");fseek(f,0,SEEK_END);long z=ftell(f);rewind(f);uint8_t*s=malloc(z);fread(s,1,z,f);fclose(f);unsigned long long q=ZSTD_getFrameContentSize(s,z);uint8_t*d=malloc(q);size_t got=ZSTD_decompress(d,q,s,z);free(s);if(ZSTD_isError(got)||got!=q)die("zstd");*n=got;return d;}
static int wanted(uint32_t m){return m==1040||m==1042||m==1044||m==1102||m==1214||m==1216||m==1222;}
int main(int argc,char**argv){if(argc!=2)return 2;char pat[4096];snprintf(pat,sizeof(pat),"%s/chunks/*.tcap.zst",argv[1]);glob_t g={0};if(glob(pat,0,NULL,&g))die("chunks");uint8_t*dom[4]={0};uint32_t dsz[4]={0};for(size_t f=0;f<g.gl_pathc;f++){size_t n;uint8_t*b=inflate(g.gl_pathv[f],&n);R r={b,b+n};if(memcmp(take(&r,8),"DSTCAP01",8)||u32(&r)!=1)die("header");uint32_t mode=u32(&r);(void)u64(&r);uint32_t names=u32(&r);for(uint32_t i=0;i<names;i++)take(&r,u16(&r));while(r.p<r.e){if(u8(&r)!=1)die("tag");uint64_t frame=u64(&r);(void)u64(&r);uint32_t movie=u32(&r);(void)u32(&r);(void)u32(&r);for(uint32_t i=0;i<names;i++)(void)u32(&r);for(int d=0;d<3;d++){uint32_t id=u32(&r),sz=u32(&r),runs=u32(&r);take(&r,32);if(!dom[id]){dom[id]=calloc(1,sz);dsz[id]=sz;}for(uint32_t j=0;j<runs;j++){uint32_t o=u32(&r),l=u32(&r);memcpy(dom[id]+o,take(&r,l),l);}}uint64_t flows=u64(&r);for(uint64_t j=0;j<flows;j++){(void)u32(&r);if(mode==1)(void)u64(&r);else{(void)u32(&r);(void)u64(&r);}}if(wanted(movie)){const uint8_t*ram=dom[1];uint32_t off=at32(ram,0xa655c),actor=0x9fd80+off;printf("m%u f%"PRIu64" mode=%u off=0x%08x player=(%d,%d,%d) bytesA0=",movie,frame,ram[0xa65a3],off,(int32_t)at32(ram,0xa6500),(int32_t)at32(ram,0xa6504),(int32_t)at32(ram,0xa6508));for(int i=0;i<8;i++)printf("%02x",ram[0xa65a0+i]);puts("");if(off&&actor+0x84<=dsz[1])printf("  actor=0x800%05x pos=(%d,%d,%d) behavior40=%u flags5c=0x%04x field5e=%u ptr80=0x%08x\n",actor,(int32_t)at32(ram,actor+4),(int32_t)at32(ram,actor+8),(int32_t)at32(ram,actor+12),at32(ram,actor+0x40),at16(ram,actor+0x5c),at16(ram,actor+0x5e),at32(ram,actor+0x80));}}
free(b);}globfree(&g);for(int i=1;i<=3;i++)free(dom[i]);return 0;}
